{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.Myntra_SJIT_INV_report as WITH mp_noos_mapping AS ( select MP_SKU_GROUP, EXISTING_SKU_GROUP from snitch_db.maplemonk.GS_MP_NOOS_SHEET1 ), inv_sent AS ( SELECT COALESCE( map.existing_sku_group || \'-\' || SPLIT_PART(factsss.sku, \'-\', -1), factsss.sku ) AS sku, COALESCE(TO_DATE(sheet.SLOT_DATE, \'DD/MM/YYYY\'), TO_DATE(sheet.ORDER_DATE, \'DD/MM/YYYY\'), factsss.ORDER_DATE) AS inward_date, SUM(factsss.SUBORDER_QUANTITY) AS qty_sent FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate AS factsss LEFT JOIN snitch_db.maplemonk.gs_mpforwards_sheet1 AS sheet ON factsss.order_id = sheet.SO_NUMBER AND sheet.MARKETPLACE = \'MYNTRA_SJIT\' LEFT JOIN mp_noos_mapping map ON REGEXP_REPLACE(factsss.sku, \'-[^-]*$\', \'\') = map.mp_sku_group WHERE factsss.marketplace_mapped = \'MYNTRA_SJIT\' AND factsss.SALE_ORDER_ITEM_STATUS NOT IN (\'CANCELLED\', \'UNFULFILLABLE\') GROUP BY 1, 2 ) , sales_and_returns AS ( SELECT sku, order_date, SUM(total_quantity) AS sales_qty, SUM(return_quantity) AS ret_qty FROM snitch_db.maplemonk.Myntra_Sjit_fact_item GROUP BY 1, 2 ), min_dates AS ( SELECT sku, MIN(event_date) AS first_event_date FROM ( SELECT sku, inward_date AS event_date FROM inv_sent WHERE sku IS NOT NULL AND inward_date IS NOT NULL UNION ALL SELECT sku, order_date AS event_date FROM sales_and_returns WHERE sku IS NOT NULL AND order_date IS NOT NULL ) GROUP BY 1 ), date_expanded AS ( SELECT m.sku, DATEADD(DAY, s.seq, m.first_event_date) AS generated_date FROM min_dates m, LATERAL ( SELECT SEQ4() AS seq FROM TABLE(GENERATOR(ROWCOUNT => 10000)) ) s WHERE DATEADD(DAY, s.seq, m.first_event_date) <= CURRENT_DATE() + 1 ), base_data AS ( SELECT d.sku, d.generated_date AS date, COALESCE(i.qty_sent, 0) as qty_sent, COALESCE(sr.sales_qty, 0) as sales_qty, COALESCE(sr.ret_qty, 0) as ret_qty FROM date_expanded d LEFT JOIN inv_sent i ON d.sku = i.sku AND d.generated_date = i.inward_date FULL OUTER JOIN sales_and_returns sr ON d.sku = sr.sku AND d.generated_date = sr.order_date ), ordered_data AS ( SELECT sku, date, qty_sent, sales_qty, ret_qty FROM base_data ), initial_rows AS ( SELECT sku, date, qty_sent, sales_qty, ret_qty, qty_sent AS opening_inventory, qty_sent - sales_qty + ret_qty AS closing_inventory FROM ordered_data WHERE (sku, date) IN ( SELECT sku, MIN(date) FROM ordered_data GROUP BY sku ) ), recursive_inventory AS ( SELECT * FROM initial_rows UNION ALL SELECT curr.sku, curr.date, curr.qty_sent, curr.sales_qty, curr.ret_qty, prev.closing_inventory AS opening_inventory, prev.closing_inventory + curr.qty_sent - curr.sales_qty + curr.ret_qty AS closing_inventory FROM recursive_inventory prev JOIN ordered_data curr ON curr.sku = prev.sku AND curr.date = DATEADD(DAY, 1, prev.date) ), with_sku_group AS ( SELECT *, REGEXP_REPLACE(sku, \'-[^-]*$\', \'\') AS sku_group, CASE WHEN sku LIKE \'%-%\' THEN SPLIT_PART(sku, \'-\', ARRAY_SIZE(SPLIT(sku, \'-\'))) ELSE NULL END AS size FROM recursive_inventory ), latest_metafields AS ( SELECT sku_group, category, title, material_new, print_design, fit, sleeve_type, collar_new FROM snitch_db.maplemonk.metafields_data ), fallback_metafields AS ( SELECT SKU_GROUP, CATEGORY, TITLE, MATERIAL_NEW, PRINT_DESIGN, FIT, SLEEVE_TYPE, COLLAR_NEW FROM snitch_db.maplemonk.GS_MP_SKU_META_SHEET1 QUALIFY ROW_NUMBER() OVER(PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) = 1 ), mp_categories AS ( SELECT DISTINCT REGEXP_REPLACE(SKU, \'-[^-]*$\', \'\') AS sku_group, ANY_VALUE(CATEGORY) AS category FROM snitch_db.maplemonk.LOGIC_FINAL_ITEM_MASTER WHERE SKU LIKE \'MP%\' GROUP BY 1 ) SELECT w.sku, w.sku_group, w.size, w.date, w.qty_sent, w.sales_qty, w.ret_qty, w.opening_inventory, w.closing_inventory, INITCAP(COALESCE(mpc.category, m.category, fb.CATEGORY)) AS category, COALESCE(m.title, fb.TITLE) AS title, COALESCE(m.material_new, fb.MATERIAL_NEW) AS material_new, COALESCE(m.print_design, fb.PRINT_DESIGN) AS print_design, COALESCE(m.fit, fb.FIT) AS fit, COALESCE(m.sleeve_type, fb.SLEEVE_TYPE) AS sleeve_type, COALESCE(m.collar_new, fb.COLLAR_NEW) AS collar_new FROM with_sku_group w LEFT JOIN latest_metafields m ON w.sku_group = m.sku_group LEFT JOIN mp_categories mpc ON w.sku_group = mpc.sku_group LEFT JOIN fallback_metafields fb ON w.sku_group = fb.SKU_GROUP ORDER BY w.sku, w.date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            